(function() {
    'use strict';

    class SerendiCityAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'SerendiCity: Strategic Serendipity Under Uncertainty';
            this.version = '1.1.0';

            this.ROUND_ALLOCATIONS = [12, 8, 9, 12, 14];

            // Each round carries fully parallel en/es content so that the whole
            // playable body (titles, briefings, labels, options) is localized,
            // not just the UI chrome.
            this.ROUNDS = [
                {
                    en: {
                        title: 'Round 1: Planned Strategy vs. Exploration Slack',
                        briefing: 'The Board has approved a five-year strategic plan emphasizing operational improvement in mining and agriculture. Your Chief Strategy Officer warns the plan is vulnerable to market disruption and proposes allocating capital to exploratory initiatives and organizational slack. Your CFO counters that exploration reduces near-term earnings and creates investor confusion.<br><br><strong>Allocation this round: $12M of discretionary capital.</strong>',
                        primaryLabel: 'Capital Allocation Philosophy',
                        secondaryLabel: 'Organizational Slack Investment',
                        primaryOptions: [
                            'A: Plan Dominance (90% core, 10% exploration)',
                            'B: Balanced (70% planned, 30% exploration)',
                            'C: Exploration Bias (50% planned, 50% exploration)',
                            'D: Extreme Flexibility (40% planned, 60% exploration)'
                        ],
                        secondaryOptions: [
                            'A: Minimal Slack (tight resource alignment)',
                            'B: Moderate Slack (8-10% excess capacity)',
                            'C: Meaningful Slack (12-15% excess capacity)',
                            'D: Substantial Slack (18-20% excess capacity)'
                        ]
                    },
                    es: {
                        title: 'Ronda 1: Estrategia Planificada vs. Holgura para Exploración',
                        briefing: 'El Directorio aprobó un plan estratégico a cinco años centrado en la mejora operativa en minería y agricultura. Tu Directora de Estrategia advierte que el plan es vulnerable a la disrupción del mercado y propone asignar capital a iniciativas exploratorias y a holgura organizacional. Tu CFO replica que la exploración reduce las ganancias a corto plazo y genera confusión en los inversionistas.<br><br><strong>Asignación de esta ronda: $12M de capital discrecional.</strong>',
                        primaryLabel: 'Filosofía de Asignación de Capital',
                        secondaryLabel: 'Inversión en Holgura Organizacional',
                        primaryOptions: [
                            'A: Dominio del Plan (90% núcleo, 10% exploración)',
                            'B: Equilibrado (70% planificado, 30% exploración)',
                            'C: Sesgo Exploratorio (50% planificado, 50% exploración)',
                            'D: Flexibilidad Extrema (40% planificado, 60% exploración)'
                        ],
                        secondaryOptions: [
                            'A: Holgura Mínima (alineación estricta de recursos)',
                            'B: Holgura Moderada (8-10% de capacidad ociosa)',
                            'C: Holgura Significativa (12-15% de capacidad ociosa)',
                            'D: Holgura Sustancial (18-20% de capacidad ociosa)'
                        ]
                    }
                },
                {
                    en: {
                        title: 'Round 2: Serendipitous Partnership Opportunity',
                        briefing: 'An unexpected opportunity emerges: TerraMetrics, a climate analytics startup in Santiago, seeks investment for a 30% equity stake. The startup uses satellite imagery and machine learning to optimize agricultural operations. Success probability: 50-60%. Potential EBITDA: $3-5M within 3 years. This is precisely the kind of serendipitous opportunity emerging from weak ties.<br><br><strong>Allocation this round: $8M of discretionary capital.</strong>',
                        primaryLabel: 'TerraMetrics Investment Decision',
                        secondaryLabel: 'Integration Approach',
                        primaryOptions: [
                            'A: Full Commitment ($20M for 30% equity)',
                            'B: Moderate Investment ($12M for 18% equity)',
                            'C: Pilot Investment ($3M for 5% equity)',
                            'D: Pass (decline, focus on planned strategy)'
                        ],
                        secondaryOptions: [
                            'A: Deep Integration (board seat, team alignment)',
                            'B: Structured Partnership (observer rights, reviews)',
                            'C: Loose Engagement (minority investor, opportunistic)',
                            'D: Observational (monitor only, revisit later)'
                        ]
                    },
                    es: {
                        title: 'Ronda 2: Oportunidad de Alianza por Serendipia',
                        briefing: 'Surge una oportunidad inesperada: TerraMetrics, una startup de analítica climática en Santiago, busca inversión a cambio de un 30% de participación. La startup usa imágenes satelitales y aprendizaje automático para optimizar operaciones agrícolas. Probabilidad de éxito: 50-60%. EBITDA potencial: $3-5M en 3 años. Es exactamente el tipo de oportunidad fortuita que emerge de los vínculos débiles.<br><br><strong>Asignación de esta ronda: $8M de capital discrecional.</strong>',
                        primaryLabel: 'Decisión de Inversión en TerraMetrics',
                        secondaryLabel: 'Enfoque de Integración',
                        primaryOptions: [
                            'A: Compromiso Total ($20M por 30% de participación)',
                            'B: Inversión Moderada ($12M por 18% de participación)',
                            'C: Inversión Piloto ($3M por 5% de participación)',
                            'D: Pasar (declinar, enfocarse en el plan)'
                        ],
                        secondaryOptions: [
                            'A: Integración Profunda (asiento en directorio, alineación de equipos)',
                            'B: Alianza Estructurada (derechos de observador, revisiones)',
                            'C: Vínculo Flexible (inversionista minoritario, oportunista)',
                            'D: Observación (solo monitorear, revisar más adelante)'
                        ]
                    }
                },
                {
                    en: {
                        title: 'Round 3: Black Swan Market Disruption',
                        briefing: 'A macroeconomic shock hits: copper and lithium prices decline 25%, expected to persist 18-24 months. Simultaneously, Bolivia proposes new environmental regulations requiring 30% more capital investment in mining. Mining EBITDA projected to decline from $94M to $55-65M. The assumptions underlying your five-year plan have been violated.<br><br><strong>Allocation this round: $9M of discretionary capital.</strong>',
                        primaryLabel: 'Crisis Response Strategy',
                        secondaryLabel: 'Capital Reallocation Response',
                        primaryOptions: [
                            'A: Aggressive Restructuring (cut mining 25%, redeploy)',
                            'B: Cost Optimization (15% opex reduction, maintain volume)',
                            'C: Defensive Stabilization (maintain production, defer capex)',
                            'D: Strategic Shift (accelerate transition from mining)'
                        ],
                        secondaryOptions: [
                            'A: Preserve Mining (all capital to mining, cut exploration)',
                            'B: Balanced (fund mining needs + maintain some growth)',
                            'C: Opportunistic (minimum mining, redirect to growth)',
                            'D: Reorientation (minimum mining, aggressive growth pivot)'
                        ]
                    },
                    es: {
                        title: 'Ronda 3: Disrupción de Mercado (Cisne Negro)',
                        briefing: 'Golpea un shock macroeconómico: los precios del cobre y el litio caen 25%, con una persistencia esperada de 18-24 meses. Al mismo tiempo, Bolivia propone nuevas regulaciones ambientales que exigen 30% más de inversión de capital en minería. Se proyecta que el EBITDA minero caiga de $94M a $55-65M. Los supuestos que sustentan tu plan a cinco años han sido violados.<br><br><strong>Asignación de esta ronda: $9M de capital discrecional.</strong>',
                        primaryLabel: 'Estrategia de Respuesta a la Crisis',
                        secondaryLabel: 'Respuesta de Reasignación de Capital',
                        primaryOptions: [
                            'A: Reestructuración Agresiva (recortar minería 25%, reasignar)',
                            'B: Optimización de Costos (reducir opex 15%, mantener volumen)',
                            'C: Estabilización Defensiva (mantener producción, diferir capex)',
                            'D: Giro Estratégico (acelerar la transición fuera de la minería)'
                        ],
                        secondaryOptions: [
                            'A: Preservar Minería (todo el capital a minería, recortar exploración)',
                            'B: Equilibrado (financiar minería + mantener algo de crecimiento)',
                            'C: Oportunista (minería mínima, redirigir a crecimiento)',
                            'D: Reorientación (minería mínima, giro agresivo a crecimiento)'
                        ]
                    }
                },
                {
                    en: {
                        title: 'Round 4: Pivot or Persist at the Inflection Point',
                        briefing: 'The market disruption has persisted 6-8 months with no clear resolution. The critical strategic question: Is this a temporary cyclical disruption that will recover in 12-18 months, or a structural shift requiring fundamental business model change? Your judgment here is the highest-stakes decision, and the outcome will only be clear retrospectively.<br><br><strong>Allocation this round: $12M of discretionary capital.</strong>',
                        primaryLabel: 'Fundamental Market Assessment',
                        secondaryLabel: 'Capital Strategy Direction',
                        primaryOptions: [
                            'A: Cyclical View (temporary, position for recovery)',
                            'B: Structural Shift (permanent change, new model needed)',
                            'C: Uncertain (maintain dual optionality, hedge)',
                            'D: Transformational (fundamental repositioning required)'
                        ],
                        secondaryOptions: [
                            'A: Accumulate for Recovery (build cash reserves)',
                            'B: Shift to Non-Commodity (systematic redirect)',
                            'C: Hedging Portfolio (balanced dual optionality)',
                            'D: Transformation Capital (maximum to new model)'
                        ]
                    },
                    es: {
                        title: 'Ronda 4: Pivotar o Persistir en el Punto de Inflexión',
                        briefing: 'La disrupción del mercado ha persistido 6-8 meses sin una resolución clara. La pregunta estratégica crítica: ¿es esta una disrupción cíclica temporal que se recuperará en 12-18 meses, o un cambio estructural que exige transformar el modelo de negocio? Tu criterio aquí es la decisión de mayor riesgo, y el resultado solo será claro en retrospectiva.<br><br><strong>Asignación de esta ronda: $12M de capital discrecional.</strong>',
                        primaryLabel: 'Evaluación Fundamental del Mercado',
                        secondaryLabel: 'Dirección Estratégica de Capital',
                        primaryOptions: [
                            'A: Visión Cíclica (temporal, posicionarse para la recuperación)',
                            'B: Cambio Estructural (cambio permanente, se necesita nuevo modelo)',
                            'C: Incierto (mantener doble opcionalidad, cobertura)',
                            'D: Transformacional (se requiere reposicionamiento fundamental)'
                        ],
                        secondaryOptions: [
                            'A: Acumular para la Recuperación (construir reservas de caja)',
                            'B: Migrar a No-Commodity (redirección sistemática)',
                            'C: Portafolio de Cobertura (doble opcionalidad equilibrada)',
                            'D: Capital de Transformación (máximo al nuevo modelo)'
                        ]
                    }
                },
                {
                    en: {
                        title: 'Round 5: Designing Organizational Architecture for Serendipity',
                        briefing: 'Design the long-term organizational architecture for capturing serendipity at scale. Based on your experience in Rounds 1-4, what level of exploration investment and governance formality would enable Altiplano to balance strategic discipline with emergent opportunity recognition? This round synthesizes your learning into sustainable capability.<br><br><strong>Allocation this round: $14M of discretionary capital.</strong>',
                        primaryLabel: 'Long-Term Exploration Budget',
                        secondaryLabel: 'Governance Design Philosophy',
                        primaryOptions: [
                            'A: Conservative (10-15% of discretionary to exploration)',
                            'B: Moderate (15-20% of discretionary to exploration)',
                            'C: Ambitious (20-25% of discretionary to exploration)',
                            'D: Bold (25-30% of discretionary to exploration)'
                        ],
                        secondaryOptions: [
                            'A: High Formalization (rigorous business cases, controls)',
                            'B: Standard (documented criteria, semi-formal approvals)',
                            'C: Light Touch (verbal criteria, business unit autonomy)',
                            'D: Minimal (trust-based, exploration assumed unless blocked)'
                        ]
                    },
                    es: {
                        title: 'Ronda 5: Arquitectura Organizacional para la Serendipia',
                        briefing: 'Diseña la arquitectura organizacional de largo plazo para capturar la serendipia a escala. Con base en tu experiencia en las Rondas 1-4, ¿qué nivel de inversión en exploración y qué formalidad de gobierno permitirían a Altiplano equilibrar la disciplina estratégica con el reconocimiento de oportunidades emergentes? Esta ronda sintetiza tu aprendizaje en una capacidad sostenible.<br><br><strong>Asignación de esta ronda: $14M de capital discrecional.</strong>',
                        primaryLabel: 'Presupuesto de Exploración a Largo Plazo',
                        secondaryLabel: 'Filosofía de Gobierno Corporativo',
                        primaryOptions: [
                            'A: Conservador (10-15% del discrecional a exploración)',
                            'B: Moderado (15-20% del discrecional a exploración)',
                            'C: Ambicioso (20-25% del discrecional a exploración)',
                            'D: Audaz (25-30% del discrecional a exploración)'
                        ],
                        secondaryOptions: [
                            'A: Alta Formalización (casos de negocio rigurosos, controles)',
                            'B: Estándar (criterios documentados, aprobaciones semiformales)',
                            'C: Ligera (criterios verbales, autonomía de las unidades)',
                            'D: Mínima (basada en confianza, exploración por defecto)'
                        ]
                    }
                }
            ];
        }

        _lang() {
            var l = (window.mySimulation && window.mySimulation.language) ||
                    (document.documentElement && document.documentElement.lang) || 'en';
            return (l === 'es') ? 'es' : 'en';
        }

        // Language-resolved content for a round (1-based period).
        _L(period) {
            var idx = Math.min((period || 1) - 1, this.ROUNDS.length - 1);
            var r = this.ROUNDS[idx];
            return r[this._lang()] || r.en;
        }

        _t(key, params) {
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                return window.mySimulation.t(key, params);
            }
            return key;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    revenue: 800,
                    ebitda: 224,
                    capitalRemaining: 55,
                    explorationValue: 0,
                    adaptabilityScore: 0,
                    miningRevenue: 440,
                    nonCommodityRevenue: 360,
                    ebitdaMargin: 28,
                    slackLevel: 0,
                    terraMetricsInvested: false,
                    terraMetricsAmount: 0,
                    cumulativeFinancialImpact: 0,
                    revenueHistory: [],
                    ebitdaHistory: [],
                    miningHistory: [],
                    nonCommodityHistory: [],
                    eventLog: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    primaryChoice: 0,
                    secondaryChoice: 0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            // Read the learner's current selections. IMPORTANT: do NOT rebuild the
            // selects here — rebuilding resets each <select> to option 0 and would
            // discard the learner's choice. The briefing/selects for the next round
            // are rendered at the end of calculateResults instead.
            var primaryEl = document.getElementById('primarySelect');
            if (primaryEl) {
                var pv = parseInt(primaryEl.value, 10);
                decisions.primaryChoice = Number.isFinite(pv) ? pv : 0;
            }

            var secondaryEl = document.getElementById('secondarySelect');
            if (secondaryEl) {
                var sv = parseInt(secondaryEl.value, 10);
                decisions.secondaryChoice = Number.isFinite(sv) ? sv : 0;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            var roundIdx = round - 1;
            var alloc = this.ROUND_ALLOCATIONS[roundIdx] || 0;

            var ebitdaDelta = 0;
            var revenueDelta = 0;
            var explorationGain = 0;
            var adaptGain = 0;
            var eventMessage = '';
            var eventTriggered = false;

            ds.capitalRemaining -= alloc;

            if (round === 1) {
                var r1Primary = [
                    { ebitda: 3.2, exploration: 0 },
                    { ebitda: 2.2, exploration: 0.8 },
                    { ebitda: 1.3, exploration: 1.8 },
                    { ebitda: -0.1, exploration: 2.5 }
                ];
                var r1Adapt = [0, 5, 10, 15];
                var pick = r1Primary[d.primaryChoice] || r1Primary[0];
                ebitdaDelta = pick.ebitda;
                explorationGain = pick.exploration;
                adaptGain = r1Adapt[d.secondaryChoice] || 0;
                ds.slackLevel = d.secondaryChoice;

                if (Math.random() < 0.60) {
                    eventTriggered = true;
                    var slackBonus = ds.slackLevel * 1.5;
                    ebitdaDelta -= (5 - slackBonus);
                    eventMessage = this._t('evt_r1_commodity');
                    if (ds.slackLevel >= 2) {
                        eventMessage += '<br>' + this._t('evt_r1_slack_help');
                        adaptGain += 3;
                    }
                }
            }

            if (round === 2) {
                var r2Impacts = [
                    { ebitda: -6.0, exploration: 3.0, terraAmt: 20 },
                    { ebitda: -2.8, exploration: 2.0, terraAmt: 12 },
                    { ebitda: -0.4, exploration: 1.2, terraAmt: 3 },
                    { ebitda: 0, exploration: 0, terraAmt: 0 }
                ];
                var r2Adapt = [4, 6, 3, 0];
                var pick2 = r2Impacts[d.primaryChoice] || r2Impacts[3];
                ebitdaDelta = pick2.ebitda;
                explorationGain = pick2.exploration;
                adaptGain = r2Adapt[d.primaryChoice] || 0;

                if (d.primaryChoice < 3) {
                    ds.terraMetricsInvested = true;
                    ds.terraMetricsAmount = pick2.terraAmt;
                }

                var integrationAdapt = [2, 4, 2, 0];
                adaptGain += integrationAdapt[d.secondaryChoice] || 0;

                if (ds.slackLevel >= 2) {
                    explorationGain += 0.5;
                    adaptGain += 2;
                }

                if (Math.random() < 0.55) {
                    eventTriggered = true;
                    if (ds.terraMetricsInvested) {
                        if (Math.random() < 0.55) {
                            ebitdaDelta += 1.5;
                            eventMessage = this._t('evt_r2_dd_positive');
                        } else {
                            ebitdaDelta -= 1.0;
                            eventMessage = this._t('evt_r2_dd_concern');
                        }
                    } else {
                        eventMessage = this._t('evt_r2_passed');
                        explorationGain -= 0.3;
                    }
                }
            }

            if (round === 3) {
                var r3Primary = [
                    { ebitda: -38, revDelta: -30 },
                    { ebitda: -15, revDelta: -10 },
                    { ebitda: -12, revDelta: -5 },
                    { ebitda: -25, revDelta: -20 }
                ];
                var r3Secondary = [
                    { adapt: 0, explorationMod: -1.0 },
                    { adapt: 4, explorationMod: 0 },
                    { adapt: 8, explorationMod: 1.0 },
                    { adapt: 10, explorationMod: 1.5 }
                ];
                var pick3p = r3Primary[d.primaryChoice] || r3Primary[1];
                var pick3s = r3Secondary[d.secondaryChoice] || r3Secondary[1];

                ebitdaDelta = pick3p.ebitda + (ds.slackLevel * 2);
                revenueDelta = pick3p.revDelta;
                ds.miningRevenue += revenueDelta;
                adaptGain = pick3s.adapt;
                explorationGain = pick3s.explorationMod;

                if (ds.terraMetricsInvested) {
                    ebitdaDelta += 2;
                    explorationGain += 0.8;
                    adaptGain += 2;
                }

                if (Math.random() < 0.60) {
                    eventTriggered = true;
                    ebitdaDelta -= 4;
                    eventMessage = this._t('evt_r3_regulatory');
                    if (d.secondaryChoice >= 2) {
                        eventMessage += '<br>' + this._t('evt_r3_growth_positioned');
                        adaptGain += 3;
                    }
                }
            }

            if (round === 4) {
                var structuralShift = Math.random() < 0.55;
                var r4Primary = [
                    { ebitdaCyclical: 8, ebitdaStructural: -10 },
                    { ebitdaCyclical: -5, ebitdaStructural: 6 },
                    { ebitdaCyclical: 2, ebitdaStructural: 2 },
                    { ebitdaCyclical: -8, ebitdaStructural: 10 }
                ];
                var r4Adapt = [2, 6, 8, 5];
                var pick4 = r4Primary[d.primaryChoice] || r4Primary[2];

                if (structuralShift) {
                    ebitdaDelta = pick4.ebitdaStructural;
                } else {
                    ebitdaDelta = pick4.ebitdaCyclical;
                }

                adaptGain = r4Adapt[d.primaryChoice] || 0;

                var r4SecondaryExpl = [0, 1.5, 2.0, 3.0];
                explorationGain = r4SecondaryExpl[d.secondaryChoice] || 0;

                if (ds.terraMetricsInvested) {
                    explorationGain += 1.0;
                    ebitdaDelta += 1.5;
                }
                if (ds.slackLevel >= 2) {
                    adaptGain += 3;
                }

                eventTriggered = true;
                if ((d.primaryChoice === 0 && structuralShift) || (d.primaryChoice >= 1 && !structuralShift)) {
                    eventMessage = this._t('evt_r4_counter') + ' ' +
                        (structuralShift ? this._t('evt_r4_counter_structural') : this._t('evt_r4_counter_cyclical'));
                    adaptGain += 2;
                } else {
                    eventMessage = this._t('evt_r4_confirm') + ' ' +
                        (structuralShift ? this._t('evt_r4_confirm_structural') : this._t('evt_r4_confirm_cyclical'));
                    ebitdaDelta += 3;
                }
            }

            if (round === 5) {
                var r5ExplBudget = [1.0, 2.0, 3.0, 4.0];
                var r5GovAdapt = [3, 6, 8, 5];
                explorationGain = r5ExplBudget[d.primaryChoice] || 0;
                adaptGain = r5GovAdapt[d.secondaryChoice] || 0;

                var coherenceBonus = 0;
                if (ds.slackLevel >= 2 && d.primaryChoice >= 2) coherenceBonus += 4;
                if (ds.terraMetricsInvested && d.primaryChoice >= 1) coherenceBonus += 3;
                if (ds.slackLevel < 2 && d.primaryChoice < 2) coherenceBonus += 3;
                adaptGain += coherenceBonus;

                ebitdaDelta = ds.explorationValue * 0.4;
                revenueDelta = ds.explorationValue * 1.2;
                ds.nonCommodityRevenue += revenueDelta;
            }

            ds.ebitda += ebitdaDelta;
            ds.revenue += revenueDelta;
            ds.explorationValue += explorationGain;
            ds.adaptabilityScore += adaptGain;
            ds.cumulativeFinancialImpact += ebitdaDelta;
            ds.ebitdaMargin = Math.round((ds.ebitda / ds.revenue) * 100 * 10) / 10;

            ds.revenueHistory.push(Math.round(ds.revenue * 10) / 10);
            ds.ebitdaHistory.push(Math.round(ds.ebitda * 10) / 10);
            ds.miningHistory.push(Math.round(ds.miningRevenue * 10) / 10);
            ds.nonCommodityHistory.push(Math.round(ds.nonCommodityRevenue * 10) / 10);

            if (eventTriggered && eventMessage) {
                ds.eventLog.push(eventMessage);
            }

            var eventEl = document.getElementById('eventPanel');
            var eventTextEl = document.getElementById('eventText');
            if (eventEl && eventTextEl) {
                if (eventTriggered && eventMessage) {
                    eventEl.style.display = 'block';
                    eventTextEl.innerHTML = eventMessage;
                } else {
                    eventEl.style.display = 'none';
                }
            }

            // Render the next round's briefing/selects synchronously (no setTimeout
            // race). currentPeriod is still the round just played; +1 targets the next.
            this._updateBriefing({ currentPeriod: state.currentPeriod + 1, _keepEvent: true });

            return {
                period: state.currentPeriod,
                roundName: this._L(round).title,
                primaryChoice: d.primaryChoice,
                secondaryChoice: d.secondaryChoice,
                ebitdaDelta: Math.round(ebitdaDelta * 10) / 10,
                explorationGain: Math.round(explorationGain * 10) / 10,
                adaptGain: Math.round(adaptGain),
                revenue: Math.round(ds.revenue * 10) / 10,
                ebitda: Math.round(ds.ebitda * 10) / 10,
                capitalRemaining: Math.round(ds.capitalRemaining * 10) / 10,
                explorationValue: Math.round(ds.explorationValue * 10) / 10,
                adaptabilityScore: Math.round(ds.adaptabilityScore),
                eventTriggered: eventTriggered
            };
        }

