        getPerformanceSummary(history) {
            if (!history.length) return {};

            var lastRecord = history[history.length - 1];
            var results = lastRecord.results || {};
            var finalEbitda = results.ebitda || 224;
            var finalAdapt = results.adaptabilityScore || 0;
            var finalExploration = results.explorationValue || 0;

            var ebitdaChange = finalEbitda - 224;
            var portfolioScore = Math.min(35, Math.max(-35, Math.round((ebitdaChange / 224) * 100)));
            var adaptScore = Math.min(35, Math.round(finalAdapt * 0.6));
            var coherenceScore = Math.min(30, Math.round(finalExploration * 3));

            var totalScore = portfolioScore + adaptScore + coherenceScore;

            var performance = this._t('perf_developing');
            if (totalScore >= 60) performance = this._t('perf_excellent');
            else if (totalScore >= 40) performance = this._t('perf_strong');
            else if (totalScore >= 20) performance = this._t('perf_good');

            var insights = [];
            if (portfolioScore > 15) {
                insights.push(this._t('insight_portfolio_strong'));
            } else if (portfolioScore < 0) {
                insights.push(this._t('insight_portfolio_declined'));
            }
            if (adaptScore > 20) {
                insights.push(this._t('insight_adapt_excellent'));
            }
            if (coherenceScore > 18) {
                insights.push(this._t('insight_coherence'));
            }
            if (finalExploration < 3) {
                insights.push(this._t('insight_low_exploration'));
            }

            return {
                totalScore: totalScore,
                portfolioScore: portfolioScore,
                adaptScore: adaptScore,
                coherenceScore: coherenceScore,
                performance: performance,
                finalEbitda: Math.round(finalEbitda),
                ebitdaChange: Math.round(ebitdaChange),
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var round = state.currentPeriod;

            if (round === 1 && results.ebitdaDelta < 0) {
                return this._t('hint_r1_negative');
            }
            if (round === 2 && state.domainState.slackLevel < 2 && results.primaryChoice < 3) {
                return this._t('hint_r2_low_slack');
            }
            if (round === 3 && results.ebitdaDelta < -20) {
                return this._t('hint_r3_heavy_loss');
            }
            if (round === 4 && results.eventTriggered) {
                return this._t('hint_r4_countervailing');
            }
            if (round >= 3 && state.domainState.capitalRemaining < 15) {
                return this._t('hint_low_capital');
            }
            return null;
        }

